CREATE TABLE schema_migrations (
  version INTEGER PRIMARY KEY NOT NULL,
  name TEXT NOT NULL,
  checksum TEXT NOT NULL,
  applied_at INTEGER NOT NULL
) STRICT;
CREATE TABLE users (
  id TEXT PRIMARY KEY NOT NULL,
  email TEXT NOT NULL UNIQUE CHECK (email = lower(email) AND instr(email, '@') > 0),
  display_name TEXT,
  idp TEXT,
  idp_subject TEXT,
  role TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'member')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  disabled_at INTEGER,
  CHECK ((idp IS NULL) = (idp_subject IS NULL))
) STRICT;
CREATE TABLE instances (
  id TEXT PRIMARY KEY NOT NULL,
  label TEXT NOT NULL,
  base_url TEXT NOT NULL UNIQUE CHECK (base_url GLOB 'http://*' OR base_url GLOB 'https://*'),
  tls TEXT CHECK (tls IS NULL OR (json_valid(tls) AND json_type(tls) = 'object')),
  number_prefixes TEXT CHECK (number_prefixes IS NULL OR (json_valid(number_prefixes) AND json_type(number_prefixes) = 'object')),
  meta_fingerprint TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  disabled_at INTEGER
) STRICT;
CREATE TABLE credentials (
  id TEXT PRIMARY KEY NOT NULL,
  instance_id TEXT NOT NULL REFERENCES instances (id) ON DELETE RESTRICT,
  owner_user_id TEXT REFERENCES users (id) ON DELETE RESTRICT,
  label TEXT NOT NULL,
  token_ciphertext TEXT NOT NULL,
  token_iv TEXT NOT NULL,
  key_version INTEGER NOT NULL CHECK (key_version >= 1),
  token_hint TEXT NOT NULL CHECK (length(token_hint) <= 4),
  validation_status TEXT NOT NULL CHECK (validation_status IN ('unvalidated', 'valid', 'invalid')),
  validation_error_code TEXT,
  validated_at INTEGER,
  member_oid TEXT,
  member_name TEXT,
  member_username TEXT,
  reachable_scope_ids TEXT CHECK (reachable_scope_ids IS NULL OR (json_valid(reachable_scope_ids) AND json_type(reachable_scope_ids) = 'array')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  revoked_at INTEGER
) STRICT;
CREATE TABLE workspaces (
  id TEXT PRIMARY KEY NOT NULL,
  slug TEXT NOT NULL UNIQUE CHECK (length(slug) BETWEEN 1 AND 63 AND slug NOT GLOB '*[^a-z0-9-]*'),
  name TEXT NOT NULL,
  instance_id TEXT NOT NULL REFERENCES instances (id) ON DELETE RESTRICT,
  allowed_scope_ids TEXT NOT NULL CHECK ((json_valid(allowed_scope_ids) AND json_type(allowed_scope_ids) = 'array')),
  include_child_scopes INTEGER NOT NULL CHECK (include_child_scopes IN (0, 1)),
  asset_types TEXT CHECK (asset_types IS NULL OR (json_valid(asset_types) AND json_type(asset_types) = 'object')),
  enabled_tools TEXT CHECK (enabled_tools IS NULL OR (json_valid(enabled_tools) AND json_type(enabled_tools) = 'array')),
  limits TEXT NOT NULL CHECK ((json_valid(limits) AND json_type(limits) = 'object')),
  default_credential_id TEXT REFERENCES credentials (id) ON DELETE RESTRICT,
  write_policy TEXT NOT NULL CHECK ((json_valid(write_policy) AND json_type(write_policy) = 'object')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  disabled_at INTEGER
) STRICT;
CREATE TABLE grants (
  id TEXT PRIMARY KEY NOT NULL,
  workspace_id TEXT NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
  user_id TEXT REFERENCES users (id) ON DELETE RESTRICT,
  label TEXT,
  credential_id TEXT REFERENCES credentials (id) ON DELETE RESTRICT,
  tools TEXT CHECK (tools IS NULL OR (json_valid(tools) AND json_type(tools) = 'array')),
  scope_ids TEXT CHECK (scope_ids IS NULL OR (json_valid(scope_ids) AND json_type(scope_ids) = 'array')),
  asset_types TEXT CHECK (asset_types IS NULL OR (json_valid(asset_types) AND json_type(asset_types) = 'object')),
  limits TEXT NOT NULL CHECK ((json_valid(limits) AND json_type(limits) = 'object')),
  rate_limit TEXT CHECK (rate_limit IS NULL OR (json_valid(rate_limit) AND json_type(rate_limit) = 'object')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  expires_at INTEGER,
  revoked_at INTEGER,
  CHECK (user_id IS NOT NULL OR label IS NOT NULL)
) STRICT;
CREATE TABLE access_tokens (
  id TEXT PRIMARY KEY NOT NULL,
  grant_id TEXT NOT NULL REFERENCES grants (id) ON DELETE CASCADE,
  prefix TEXT NOT NULL CHECK (length(prefix) = 12 AND (prefix GLOB 'ab_live_*' OR prefix GLOB 'ab_test_*') AND substr(prefix, 9) NOT GLOB '*[^0-9A-Za-z]*'),
  token_hash TEXT NOT NULL UNIQUE CHECK (length(token_hash) = 64 AND token_hash NOT GLOB '*[^0-9a-f]*'),
  label TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  expires_at INTEGER,
  last_used_at INTEGER,
  revoked_at INTEGER
) STRICT;
CREATE TABLE audit_log (
  id TEXT PRIMARY KEY NOT NULL,
  ts INTEGER NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('tool_call', 'write', 'auth', 'admin')),
  action TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('ok', 'error', 'denied')),
  request_id TEXT,
  user_id TEXT,
  grant_id TEXT,
  token_id TEXT,
  client_id TEXT,
  workspace_id TEXT,
  instance_id TEXT,
  asset_numbers TEXT CHECK (asset_numbers IS NULL OR (json_valid(asset_numbers) AND json_type(asset_numbers) = 'array')),
  query TEXT,
  duration_ms INTEGER,
  agility_requests INTEGER,
  error_code TEXT,
  target_type TEXT,
  target_id TEXT,
  details TEXT CHECK (details IS NULL OR (json_valid(details) AND json_type(details) = 'object'))
) STRICT;
CREATE TABLE settings (
  key TEXT PRIMARY KEY NOT NULL,
  value TEXT NOT NULL CHECK (json_valid(value)),
  updated_at INTEGER NOT NULL
) STRICT;
CREATE TABLE kv (
  key TEXT PRIMARY KEY NOT NULL,
  value TEXT NOT NULL,
  expires_at INTEGER
) STRICT;
